"""Generate the executed Step 4 reference and update all project READMEs."""
from pathlib import Path
import sys,json,xml.etree.ElementTree as ET
import pandas as pd
B=Path(__file__).resolve().parents[1];ROOT=B.parent;O=B/'outputs/step4';M=B/'models/step4'
sys.path.insert(0,str(B/'src'))
from pathsnap.modeling import FEATURES

def main():
    comparison=pd.read_csv(O/'model_comparison.csv');fold=pd.read_csv(O/'fold_metrics.csv');meta=json.loads((O/'training_metadata.json').read_text())
    config=json.loads((M/'model_configurations.json').read_text());counts=meta['counts'];selected=json.loads((O/'preliminary_selection.json').read_text())
    suites=list(ET.parse(O/'pytest-results.xml').getroot().iter('testsuite'));tests={k:sum(int(s.get(k,0)) for s in suites) for k in ['tests','failures','errors','skipped']}
    descriptions={
    'logistic_regression':('A scaled linear log-odds boundary with L2 regularisation. Fast, interpretable baseline; limited without nonlinear feature interactions. Coefficients refer to standardized imputed inputs, not causal effects.'),
    'gaussian_nb':('Combines Gaussian class-conditional feature densities under conditional independence. Cheap probabilistic baseline; correlated geometric features violate independence and can yield overconfident scores. Scaling supports numerical stability but does not make the independence assumption true.'),
    'decision_tree':('Recursively splits features to reduce classification impurity. Captures nonlinear rules, is easy to inspect, but can vary across trips. Depth and minimum leaf size bound overfitting.'),
    'random_forest':('Averages bootstrapped randomized decision trees. Reduces single-tree variance and models nonlinear interactions; costs more memory/time and impurity importance can favour continuous/high-cardinality features.'),
    'hist_gradient_boosting':('Sequentially fits binned-feature trees to improve binary log loss. Captures nonlinear interactions efficiently; may overfit trip/reference-label patterns. Internal random-row early stopping is disabled to preserve the external trip-aware evaluation design.')}
    lines=['# Step 04: five baseline models and trip-grouped cross-validation','',
      '## Objective and scope','Train five distinct binary candidate classifiers and compare genuine out-of-fold ranking/classification performance. This is baseline experimentation; no student-test evaluation, hyperparameter search, route decoder, API/UI or deployment is implemented. Official model guidelines require at least five models and group-aware training-trip CV; student-test comparisons remain for the separately approved evaluation stage.','',
      '## Verified training dataset and preparation','```json',json.dumps(counts,indent=2),'```',
      'Feature and target tables join one-to-one using dataset_partition, trip_id, gps_observation_index and candidate_arc_id. Missing/extra/duplicate keys, non-training partitions, unexpected feature columns, illegal targets and eligibility/null disagreements fail validation. Only target-nonnull eligible rows are fitted. Every retained observation has exactly one positive candidate. Positive always means the candidate equals its eligible reference-derived arc. Null targets are excluded rather than converted to negatives. Student-test directories are never opened by training.',
      'All 80 training trips appear in exactly one held-out fold. Each of five folds has **64 fitting trips and 16 validation trips**. Candidate rows and observations remain grouped by complete trip. The saved Step 3 fold assignment is reused unchanged. Earlier wording “16 trips per fold” describes the held-out subset, not total fitting trips.','',
      '## Models: presentation-ready explanations, strengths and limitations']
    for name in config:lines += ['', '### '+name,descriptions[name],'```json',json.dumps(config[name],indent=2),'```']
    lines += ['', '## Fold-local preprocessing and fairness',meta['preprocessing'],
      'The saved Scikit-learn Pipeline requires exactly the ordered 25-feature DataFrame and rejects IDs/label/reference columns. It maps ±infinity to NaN. Median imputation, missing-indicator detection and LR/GNB standardisation fit only on each fitting subset. keep_empty_features=True retains column positions; an entirely missing fitting column uses the documented SimpleImputer zero placeholder, with missingness indicator. No global imputer/scaler is fitted before CV. The full-data pipelines later learn their own transformations from eligible training data only.',
      meta['weighting'],
      'Observation weights apply to classifier fitting. Imputer medians and scaler means/variances are ordinary unweighted statistics of the fitting candidate rows only; no validation rows contribute. This is a documented baseline choice, not a claim of weighted preprocessing.',
      'Each observation has equal total training weight, preventing larger candidate groups from dominating. Weights are not class-balanced and are normalized independently on each fitting subset. Validation metrics use ordinary unweighted candidates and observations; weighting changes fitted class priors, so probability quality must be assessed separately. All five models receive identical rows, folds and weighting. HGB internal early stopping is disabled; all 100 rounds execute. No hold-out trip or student-test feature influences learned preprocessing.','',
      '## Complete inference feature schema',
      'The exact schema is saved in models/step4/feature_schema.json. Identifiers remain metadata and are excluded. Distance and arc length use metres; bearing/heading are circular trigonometric components; endpoint distances are along the projected segment; degrees count directed arcs; flags describe input quality and candidate retrieval. Heading/speed/displacement use only current/preceding observations, with no future observations or references.']
    meanings=['GPS-to-segment metric distance','Geodesic arc endpoint length','Sine of directed arc bearing','Cosine of directed arc bearing','Sine of causal GPS heading','Cosine of causal GPS heading','Absolute circular heading disagreement, degrees','Causal implied speed, km/h','Seconds since preceding observation','Preceding GPS displacement, metres','Distance-ranked retrieval position','Closest-point directed fraction, 0..1','Metric distance along segment from start','Metric distance along segment to end','Start-node directed out-degree','End-node directed in-degree','Invalid source coordinate flag','Exact duplicated observation flag','Invalid/non-increasing timestamp flag','Gap over five seconds','Implied speed above threshold','Large displacement flag','Unavailable/stationary/invalid heading flag','Bounded fallback used','Retained candidates in observation group']
    lines += ['','| Feature | Meaning |','|---|---|']+[f'| {f} | {meaning} |' for f,meaning in zip(FEATURES,meanings)]
    lines += ['', '## Training and evaluation flow',
      'Validate saved data/folds -> per-model five fresh pipelines -> weighted fitting -> probability on held-out trips only -> OOF Parquet and fold/per-trip metrics -> fit a fresh pipeline on all eligible training rows -> Joblib persistence -> reload checks -> comparison/plots -> independent artifact/OOF verification. CV models are transient; their actual held-out predictions are persisted. Final five model files are full-data fits and never supply the reported CV scores.',
      'Candidate classification uses threshold 0.5 for precision/recall/positive F1/macro F1/accuracy and 2x2 confusion matrices. ROC-AUC and binary log loss use positive-class probability. Undefined single-class ROC-AUC is null; undefined precision/recall/F1 denominators use zero, an explicit sklearn convention. Ranking sorts probability descending and original arc ID ascending for ties within each trip/observation. Top-1 checks whether the winning row has target=1. MRR averages reciprocal true-candidate rank. Prediction coverage is the fraction of labelled candidate-present groups with finite scores; it does not measure raw-GPS candidate recall.','',
      '## Actual preliminary CV comparison','Equal weight is given to each of five held-out folds; SD uses the sample definition (ddof=1). Fold and per-trip CSVs retain actual counts. These means differ from a candidate-count-weighted pooled score.','',
      '| Model | Precision | Recall | F1 ± SD | Macro F1 | ROC-AUC | Log loss | Top-1 ± SD | MRR | Mean fitting seconds |',
      '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
    for r in comparison.itertuples():lines.append(f'| {r.model_name} | {r.precision_mean:.5f} | {r.recall_mean:.5f} | {r.f1_mean:.5f} ± {r.f1_std:.5f} | {r.macro_f1_mean:.5f} | {r.roc_auc_mean:.5f} | {r.log_loss_mean:.5f} | {r.top1_accuracy_mean:.5f} ± {r.top1_accuracy_std:.5f} | {r.mean_reciprocal_rank_mean:.5f} | {r.training_seconds_mean:.3f} |')
    lines += ['',f"Preliminary leader: **{selected['model_name']}**, selected by mean eligible-observation Top-1, with MRR and log loss as tie breakers. Its advantage over the runner-up is {(comparison.iloc[0].top1_accuracy_mean-comparison.iloc[1].top1_accuracy_mean)*100:.3f} percentage points, compared with its fold SD of {comparison.iloc[0].top1_accuracy_std*100:.3f} points. This is not an established statistically significant advantage. Its mean fold scoring time is {comparison.iloc[0].prediction_seconds_mean:.3f} s versus {comparison.iloc[1].prediction_seconds_mean:.3f} s for the runner-up. Consider stability, inference speed and log loss before treating this choice as final. No algorithm was assumed to win.",
      f"Measured invocation elapsed time: {meta['total_seconds']:.3f} s (resumed={meta.get('resumed',False)}). All 25 CV fitting durations sum to {fold.training_seconds.sum():.3f} s and CV predictions to {fold.prediction_seconds.sum():.3f} s. For a resumed run, invocation elapsed time excludes earlier cached folds; their original measured durations remain in fold_metrics.csv. There is no claimed uninterrupted total wall time. Maximum sampled process RSS during a CV fit/prediction: {fold.peak_rss_mib.max():.3f} MiB. Separate reporting/tests/verification are excluded. Two threads bound native libraries and Random Forest jobs. This is execution evidence, not a comparative speedup benchmark.",
      'Fold warnings: '+ ('none' if fold.warnings.fillna('').eq('').all() else 'Inspect fold_metrics.csv warnings column; no warning was suppressed from recorded evidence.'),'',
      'Regression tests overlapped some training folds, so runtime varies with system load and is not an isolated speed comparison. Full-fit durations are recorded separately in artifact_manifest.csv. Completed CV folds were reused only after verifying inputs, configuration and exact held-out identities; no evaluation was skipped. The forest size/depth/bootstrap bounds were chosen before any forest validation result was observed, as a computational baseline rather than a tuned optimum.','',
      'Interruption recovery reused all 25 completed validation folds and all five valid final pipelines; no training was needed during the final recovery turn. Original full-fit durations for Logistic Regression and Gaussian Naive Bayes were not retained before interruption and remain missing in the manifest. Their artifact checksums/configurations/reload predictions are verified; no duration is invented and valid fits were not repeated merely to obtain timing. CV model objects were transient, not saved; persisted genuine OOF predictions are validated, and all five final full-data pipelines are reloadable.','',
      '## Code modules and function contracts',
      '- modeling.load_training(root) -> eligible row DataFrame, saved folds and measured counts; only train/ is read.',
      '- modeling.validate_folds(rows, folds) -> held-out fold IDs; rejects duplicate/missing trip assignments.',
      '- modeling.FiniteFeatures -> inference-schema guard and infinity-to-missing transform inside the saved Pipeline.',
      '- modeling.make_pipeline(model_name) -> deterministic model/imputation/scaling pipeline.',
      '- modeling.observation_weights(rows) -> inverse group-size fitting weights with mean one.',
      '- modeling.positive_probability(pipeline, X) -> validated probability of class 1 using classifier.classes_.',
      '- modeling.ranking(predictions)/metrics(predictions) -> observation-ranking and binary-classification metrics.',
      '- scripts/train_models.py -> all 25 CV fits, five full fits, OOF predictions and artifacts.',
      '- scripts/evaluate_cv.py -> actual comparison, preliminary selection and plots without refitting.',
      '- scripts/verify_step4.py -> persisted ID/fold/probability/metric/source/checksum/reload checks.',
      '- scripts/document_step4.py -> measured stage reference and all three README updates.','',
      '## Technologies, files and outputs',
      'Python/NumPy/Pandas and Parquet reuse prior stages. New direct dependencies are Scikit-learn 1.9.1, Joblib 1.6.0 and threadpoolctl 3.8.0; SciPy and other transitive versions are pinned in requirements-lock.txt. No frontend dependencies changed.',
      'outputs/step4: dataset_validation.json, fold_integrity.csv, fold_metrics.csv, per_trip_metrics.csv, model_comparison.csv, oof/<model>/fold_<n>.parquet, preliminary_selection.json, training_metadata.json, verification.json, actual tests and STEP4_SUMMARY.md. Plots are f1_comparison.png, top1_comparison.png, training_time.png, confusion_matrices.png, probability_distributions.png and feature_effects.png. LR coefficients and tree/forest impurity importances have named-feature CSVs; GNB/HGB do not expose compatible coefficient/impurity importances and none are fabricated.',
      'models/step4: five <model>.joblib full-fit Pipelines, model_configurations.json, feature_schema.json, artifact_manifest.csv (SHA-256/bytes/full-fit duration) and training_metadata.json. Artifacts include learned imputer/scaler parameters and estimator configuration. Load only trusted Joblib artifacts; installed compatible library versions and pathsnap.modeling must be importable. For own Python clients install the backend with pip install -e . or set src/ on PYTHONPATH.','',
      '## Tests, errors and verification',json.dumps(tests),
      'The original 83 tests remain intact. Eighteen Step 4 tests cover all five pipelines, missing/infinite inputs, positive mapping, serialization, schema/label separation, fold grouping, student-test rejection, fold-local transformations, ranking/ties, metrics, undefined AUC, equal observation weights, deterministic configurations and verified resume without retraining any completed pipeline. Independent verification checks every OOF key/target/fold, recomputes metrics and confirms saved final models predict without fitting.',
      'During development an exact equality reload assertion exposed Random Forest parallel summation differences around 1e-16. Reload checks now use rtol=1e-13 and atol=1e-15; the corrected run generated final evidence. This is numerical precision, not retraining or altered labels. No existing tests were weakened.','',
      '## Exact Windows commands (from ML hackathon)', '```powershell',
      'cd .\\PathSnap\\laptop1_backend',
      '.\\.venv\\Scripts\\python.exe -m pip install -r requirements.txt',
      '.\\.venv\\Scripts\\python.exe scripts\\train_models.py',
      '.\\.venv\\Scripts\\python.exe scripts\\evaluate_cv.py',
      '.\\.venv\\Scripts\\python.exe scripts\\verify_step4.py',
      '.\\.venv\\Scripts\\python.exe -m pytest -q --junitxml=outputs\\step4\\pytest-results.xml',
      '.\\.venv\\Scripts\\python.exe scripts\\document_step4.py','```',
      'train_models.py accepts --data, --output and --models. Add --resume to reuse verified completed folds and final pipelines. Running without --resume starts a new training experiment. Other scripts expose their relevant paths. Existing earlier-stage Parquet is reused; do not regenerate candidates/alignment to train models.','',
      '## Limitations, completion and Step 5 readiness',
      'All five baselines and 25 required fold evaluations are complete. Scores measure imitation of heuristic reference-derived supervision on eligible candidate-present observations. They omit uncertain alignments and candidate misses, so they cannot establish physical-truth accuracy, end-to-end coverage or route reconstruction quality. Candidate and observation metrics have different denominators. Reference-based alignment uses fixed geometry rules similar to some features; that dependency can inflate apparent agreement. Model probabilities are independent binary scores, not normalized route probabilities. Uniform trip folds are not geographically stratified. No Bayesian optimisation, student-test label alignment/evaluation or HMM/Viterbi is included.',
      'Step 5 can load the saved full-fit Pipelines, exact ordered feature schema and OOF evidence for separately approved detailed evaluation. Any later tuning must retain fold-local transformations and untouched evaluator data. Final selection remains preliminary. No API, frontend or deployment ZIP has been built.','',
      'Changelog — 2026-11-18: Step 4 adds validated eligible training joins, five fold-local baseline pipelines, full trip-held-out CV, full fits, persistence, actual plots/tests and step-wise documentation. AI-assisted code/reporting remains subject to team review and disclosure under event policy.','']
    text='\n\n'.join(lines);(ROOT/'docs/steps/STEP_04_README.md').write_text(text,encoding='utf-8');(O/'STEP4_SUMMARY.md').write_text(text,encoding='utf-8')
    for path,prefix in [(ROOT/'README.md','docs/steps/'),(B/'README.md','../docs/steps/'),(ROOT/'laptop2_frontend/README.md','../docs/steps/')]:
        old=path.read_text(encoding='utf-8');marker='\n<!-- STEP4_CURRENT -->'
        if marker in old:old=old.split(marker)[0]
        old=old.replace('- [ ] Step 4 five models: not started.','- [x] Step 4 five baseline models and trip-grouped cross-validation; see current reference.')
        old=old.replace('**Steps 1, 2 and 3 are implemented:** exploration, geometric candidates, cleaning, training-reference alignment and inference-time features. Models, decoding and the distributed application remain pending.',
            '**Steps 1–4 are implemented:** exploration, geometric candidates, cleaning, training-reference alignment, inference-time features and five baseline models with trip-held-out CV. Detailed evaluation, optimisation, decoding and the distributed application remain pending.')
        old=old.replace('| Laptop 1 — `laptop1_backend/` | Original data, loaders, EDA, metric roads, spatial indexes, candidates and tests | Features/training, evaluation/optimisation, HMM/Viterbi, models, FastAPI, inference and server-side evaluation |',
            '| Laptop 1 — `laptop1_backend/` | Data, EDA, roads, candidates, cleaning/alignment/features, five trained baseline pipelines, CV and tests | Detailed evaluation/optimisation, HMM/Viterbi, FastAPI, inference service and server-side evaluation |')
        old=old.replace('# Laptop 1: dataset exploration and road candidates (Steps 1–2)', '# Laptop 1: data processing, features and baseline ML (Steps 1–4)')
        old=old.replace('metric roads, reusable spatial indexes and label-free GPS candidates. Training,\nHMM/Viterbi, API server and inference remain pending. Step 3 now implements supervised alignment and features.',
            'metric roads, reusable spatial indexes and label-free GPS candidates. Step 3 implements supervised alignment/features; Step 4 adds five trained baseline pipelines and trip-held-out CV. HMM/Viterbi, API server and inference service remain pending.')
        old=old.replace('ten direct dependencies;', 'thirteen direct dependencies;')
        old=old.replace('Steps 1–2 create this directory and documentation only.', 'Steps 1–4 maintain this directory and documentation only.')
        old=old.replace('**Step 3 cleaning/alignment/features; stop before Step 4**', '**Step 3 cleaning/alignment/features → Step 4 baseline ML/CV; stop before Step 5**')
        old=old.replace('# Empty; no trained models', '# Five saved Step 4 baseline pipelines')
        addition=marker+f"\n\n## Current status: Step 4 completed\n\n[Step 4 detailed reference]({prefix}STEP_04_README.md). Earlier stage status statements above describe historical boundaries. Five baseline pipelines completed five-fold trip-held-out CV (64 train / 16 held-out trips per fold) and separate full-data fits. Only eligible training data was fitted; student-test labels were not used. Preliminary leader: {selected['model_name']}. {tests['tests']} tests, {tests['failures']} failures, {tests['errors']} errors, {tests['skipped']} skipped. Models/step4 and outputs/step4 on Laptop 1 contain actual artifacts/results. Laptop 2 remains a documentation-only HTTP UI placeholder with no backend/ML dependencies.\n\nCommands, model explanations, full feature list, function contracts, metrics, model limitations and reproduction details are in the linked step reference. New backend dependencies: Scikit-learn, Joblib, threadpoolctl. No new frontend dependencies.\n\n- [x] Step 4 models/CV/artifacts/verification/documentation.\n- [ ] Step 5 detailed evaluation; not started. Optimisation, decoder, API/UI and final ZIPs remain pending.\n\nChangelog — 2026-11-18: completed Step 4 baseline training and preserved Steps 1–3 evidence. Step 5 requires explicit approval.\n"
        path.write_text(old+addition,encoding='utf-8')
    print('Step 4 technical reference, summary and three READMEs updated.')
if __name__=='__main__':main()
